import{_ as o,o as c,c as d,a2 as t}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"Processor 字节码转换与网络同步机制","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.1/sync/processor-and-network.md","filePath":"1.21.1/sync/processor-and-network.md"}'),r={name:"1.21.1/sync/processor-and-network.md"};function n(a,e,i,s,l,y){return c(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="processor-字节码转换与网络同步机制" tabindex="-1">Processor 字节码转换与网络同步机制 <a class="header-anchor" href="#processor-字节码转换与网络同步机制" aria-label="Permalink to &quot;Processor 字节码转换与网络同步机制&quot;">​</a></h1><p>本篇解释 <code>module.sync</code> 与子模块 <code>module.sync:processor</code> 在 NeoForge 1.21.1 下的底层实现机制，帮助开发者理解零手动登记是如何实现的，以及如何在复杂继承、跨维度传输或自定义网络环境下排查问题。</p><h2 id="processor-与字节码注入-icoremod-模式" tabindex="-1">Processor 与字节码注入（ICoreMod 模式） <a class="header-anchor" href="#processor-与字节码注入-icoremod-模式" aria-label="Permalink to &quot;Processor 与字节码注入（ICoreMod 模式）&quot;">​</a></h2><p>在 Maven/Gradle 中引入 <code>anvillib-sync-neoforge-1.21.1</code> 时，子模块 <code>anvillib-sync-processor-neoforge-1.21.1</code> 会通过 <code>slimJarJar</code> <strong>自动打包嵌套传递</strong>到游戏运行环境中，无需开发者手动声明处理器依赖。</p><p>在 NeoForge 1.21.1（FML Loader 4.0.x）环境下，由于尚不存在高版本的 <code>ClassProcessor</code> SPI，<code>module.sync:processor</code> 通过标准 SPI 文件：</p><p><code>META-INF/services/net.neoforged.neoforgespi.coremod.ICoreMod</code> -&gt; <code>dev.anvilcraft.lib.v2.sync.transform.SyncClassProcessor</code></p><p>向 ModLauncher 注册 ASM <code>ITransformer&lt;ClassNode&gt;</code> 类转换器。</p><h3 id="启动时序与字节码改写内容" tabindex="-1">启动时序与字节码改写内容 <a class="header-anchor" href="#启动时序与字节码改写内容" aria-label="Permalink to &quot;启动时序与字节码改写内容&quot;">​</a></h3><ol><li><strong>Mod 发现阶段（早于目标类加载）</strong>： <ul><li><code>SyncTargetIndex</code> 静态扫描 <code>LoadingModList</code> 中所有带 <code>@Sync</code> 类注解的目标类内部名与 <code>SyncDirection</code> 方向值。</li><li><code>LazySyncTargetIndex</code> 静态扫描所有带 <code>@LazySync</code> 字段注解的所属类内部名。</li></ul></li><li><strong>类加载转化阶段 (<code>SyncTransformer.transform</code>)</strong>： <ul><li>若类在 <code>SyncTargetIndex</code> 中：<code>SyncBytecodeInjector</code> 检查所有 <strong><code>final SyncProxy</code></strong> 字段，并在所有构造器 <code>&lt;init&gt;</code> 返回前注入 <code>proxy.setParent(this)</code>、<code>proxy.setFieldName(name)</code>、<code>proxy.setDirection(classDir)</code>；对于 <code>static final</code> 字段则在 <code>&lt;clinit&gt;</code>（无则自动新建）末尾注入 <code>proxy.setParent(Owner.class)</code> 等调用。</li><li>若类在 <code>LazySyncTargetIndex</code> 中：<code>LazySyncBytecodeInjector</code> 在所有 <code>&lt;init&gt;</code> 返回前注入 <code>AnvilLibSync.LAZY_SYNC_MANAGER.track(this)</code>；对于静态 <code>@LazySync</code> 字段在 <code>&lt;clinit&gt;</code> 末尾注入 <code>AnvilLibSync.LAZY_SYNC_MANAGER.trackStatic(Owner.class)</code>。</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">自动 GC 与继承支持</p><ul><li><code>LazySyncManager</code> 内部使用基于 Guava <code>MapMaker().weakKeys()</code> 的弱引用集合与快照表保存实例目标；当 <code>Entity</code> 或 <code>BlockEntity</code> 被卸载且无外界强引用时可被自动垃圾回收，<strong>无需显式反注册</strong>。</li><li><code>LazySyncManager</code> 收集元数据时沿父类链向上递归（<code>clazz -&gt; superclass -&gt; ...</code>），因此子类实例也会自动继承并同步父类中声明的 <code>@LazySync</code> 字段（条件是客户端与服务端对宿主类的识别与 <code>SyncRegisterEntry</code> 一致）。</li></ul></div><h2 id="配置同步与分包转发规则" tabindex="-1">配置同步与分包转发规则 <a class="header-anchor" href="#配置同步与分包转发规则" aria-label="Permalink to &quot;配置同步与分包转发规则&quot;">​</a></h2><h3 id="_1-configuration-阶段统一字段索引表" tabindex="-1">1. Configuration 阶段统一字段索引表 <a class="header-anchor" href="#_1-configuration-阶段统一字段索引表" aria-label="Permalink to &quot;1. Configuration 阶段统一字段索引表&quot;">​</a></h3><p>为了不在每次字段变动时传输冗长的 <code>&quot;com.example.MyTile#manaPool&quot;</code> 字符串，模块采用了与 RPC 相同的配置压缩表：</p><ul><li>模组初始化完毕（<code>FMLCommonSetupEvent</code>）后，<code>SyncConfigManager.compileContent()</code> 扫描全部 <code>@Sync</code> 类的 <code>final SyncProxy</code> 字段与 <code>@LazySync</code> 字段并分配自增 <code>int</code> 索引 <code>syncConfigId</code>。</li><li>玩家进入服务端处于 Configuration 阶段时，<code>AnvilLibSync.SyncConfig</code> 任务下发 <code>SyncConfigurationPayload(syncMap)</code>；客户端将映射写入 <code>AnvilLibSyncClient.SYNC_CONFIG_MANAGER</code> 并回复 <code>SyncConfigurationFinishPayload</code> 完成握手。</li></ul><h3 id="_2-分维度、分追踪玩家定向广播-sideutil" tabindex="-1">2. 分维度、分追踪玩家定向广播 (<code>SideUtil</code>) <a class="header-anchor" href="#_2-分维度、分追踪玩家定向广播-sideutil" aria-label="Permalink to &quot;2. 分维度、分追踪玩家定向广播 (`SideUtil`)&quot;">​</a></h3><p>当服务端发送同步包时，<code>SideUtil.serverSend(...)</code> 会根据宿主 <code>SyncRegisterEntry</code> 决定广播范围，避免无谓的全服发包：</p><table tabindex="0"><thead><tr><th>宿主条件 (<code>entry.dimension()</code> &amp; ID/对象类型)</th><th>NeoForge 发送目标</th></tr></thead><tbody><tr><td><code>dimension == false</code> 或 <code>dimensionGetter == null</code>（如 <code>STATIC</code> 静态类）</td><td><code>PacketDistributor.sendToAllPlayers(packet)</code></td></tr><tr><td>宿主 ID 为 <code>BlockPos</code>（如 <code>BLOCK_ENTITY</code>）</td><td><code>PacketDistributor.sendToPlayersTrackingChunk(level, ChunkPos(pos), packet)</code></td></tr><tr><td>宿主对象为 <code>Entity</code></td><td><code>PacketDistributor.sendToPlayersTrackingEntity(entity, packet)</code> 后并再执行维度发送（注：源码中此处未使用 <code>return</code>，因此对实体也会落到 <code>sendToPlayersInDimension</code>）</td></tr><tr><td>其他带维度对象</td><td><code>PacketDistributor.sendToPlayersInDimension(level, packet)</code></td></tr></tbody></table><p>客户端发送（<code>C2S</code> / <code>BOTH</code>）则统一调用 <code>PacketDistributor.sendToServer(...)</code>。</p><h3 id="_3-lazysyncpayload-与回环抑制" tabindex="-1">3. <code>LazySyncPayload</code> 与回环抑制 <a class="header-anchor" href="#_3-lazysyncpayload-与回环抑制" aria-label="Permalink to &quot;3. `LazySyncPayload` 与回环抑制&quot;">​</a></h3><p><code>LazySyncManager</code> 在收到对端发来的 <code>LazySyncPayload</code> 并通过反射 <code>field.set(...)</code> 写回字段后，<strong>会立即用写回后的新值重新编码一次并覆写本地快照 <code>snap.put(configKey, encoded)</code></strong>。这样可以彻底防止同一条变更在下一个 Tick 被本端误判为“本地新变更”而无限乒乓回发。</p><h2 id="内部-api-与网络载荷一览" tabindex="-1">内部 API 与网络载荷一览 <a class="header-anchor" href="#内部-api-与网络载荷一览" aria-label="Permalink to &quot;内部 API 与网络载荷一览&quot;">​</a></h2><p>尽管以下类大多标为 <code>@ApiStatus.Internal</code>，理解其职责与边界有助于编写自定义 <code>SyncRegisterEntry</code> 与调试网络包：</p><h3 id="运行时与网络类-dev-anvilcraft-lib-v2-sync" tabindex="-1">运行时与网络类 (<code>dev.anvilcraft.lib.v2.sync.*</code>) <a class="header-anchor" href="#运行时与网络类-dev-anvilcraft-lib-v2-sync" aria-label="Permalink to &quot;运行时与网络类 (`dev.anvilcraft.lib.v2.sync.*`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类名</th><th>职责与核心公开成员</th></tr></thead><tbody><tr><td><code>AnvilLibSync</code></td><td>模组入口（<code>MOD_ID = &quot;anvillib_sync&quot;</code>）；持有全局静态实例 <code>SYNC_MANAGER</code>、<code>SYNC_CONFIG_MANAGER</code>、<code>LAZY_SYNC_MANAGER</code>；注册服务端 <code>ServerTickEvent.Post</code>、<code>ServerStoppedEvent</code> 与 <code>SyncConfig</code> 配置任务</td></tr><tr><td><code>AnvilLibSyncClient</code></td><td>客户端 <code>@Mod(dist = Dist.CLIENT)</code> 入口；持有客户端 <code>SYNC_CONFIG_MANAGER</code>；驱动 <code>ClientTickEvent.Post</code> 并于 <code>ClientPlayerNetworkEvent.LoggingOut</code> 清理客户端惰性追踪表</td></tr><tr><td><code>AnvilLibSyncNetwork</code></td><td>通过 <code>NetworkRegistrar</code> 在 <code>NETWORK_VERSION = &quot;1&quot;</code> 下自动注册全模块双向包及配置包</td></tr><tr><td><code>SyncManager</code></td><td>维护 <code>Class&lt;?&gt; -&gt; SyncRegisterEntry&lt;?, ?&gt;</code> 注册表查找（支持父类/接口向下匹配 <code>isAssignableFrom</code>）与立即同步调度</td></tr><tr><td><code>LazySyncManager</code></td><td>负责实例/静态目标的 <code>@LazySync</code> 差分、分组编码及回环抑制写回（含 <code>AppliedField</code> 记录类与 <code>tickServer</code>/<code>tickClient</code>/<code>clearServer</code>/<code>clearClient</code>/<code>track</code>/<code>trackStatic</code>/<code>applyGrouped</code> 方法）</td></tr><tr><td><code>SyncConfigManager</code></td><td>ASM 扫描 <code>@Sync</code> 类字节码字段与 <code>@LazySync</code> 字段，管理 <code>String &lt;-&gt; int</code> 双向配置表</td></tr><tr><td><code>SideUtil</code></td><td>提供双端判定 <code>isServer()</code>、<code>registryAccess()</code>、<code>entityFinder</code>、<code>blockEntityFinder</code>、<code>createFriendlyByteBuf(ByteBuf)</code>（有注册表时构造 <code>RegistryFriendlyByteBuf</code>）、<code>send</code> / <code>serverSend</code> / <code>clientSend</code></td></tr><tr><td><code>SyncPayload</code></td><td>单个 <code>SyncProxy</code> 即时同步双端包（<code>anvillib_sync:sync</code>）</td></tr><tr><td><code>LazySyncPayload</code></td><td>按宿主对象合批的惰性同步双端包（<code>anvillib_sync:lazy_sync</code>），含嵌套 record <code>FieldChange(String configKey, byte[] blob)</code></td></tr><tr><td><code>SyncConfigurationPayload</code> / <code>Finish</code></td><td>Configuration 阶段配置表同步包（<code>anvillib_sync:sync_config</code> / <code>anvillib_sync:sync_config_finish</code>）</td></tr></tbody></table><h3 id="processor-字节码注入类-dev-anvilcraft-lib-v2-sync-transform" tabindex="-1">Processor 字节码注入类 (<code>dev.anvilcraft.lib.v2.sync.transform</code>) <a class="header-anchor" href="#processor-字节码注入类-dev-anvilcraft-lib-v2-sync-transform" aria-label="Permalink to &quot;Processor 字节码注入类 (`dev.anvilcraft.lib.v2.sync.transform`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类名</th><th>说明</th></tr></thead><tbody><tr><td><code>SyncClassProcessor</code></td><td>实现 <code>ICoreMod</code> 并暴露 <code>SyncTransformer</code>，将目标类交给 <code>@Sync</code> 与 <code>@LazySync</code> 注入器</td></tr><tr><td><code>SyncTargetIndex</code> / <code>LazySyncTargetIndex</code></td><td>从 <code>LoadingModList</code> 注解扫描结果预先构建待变换目标类索引</td></tr><tr><td><code>SyncBytecodeInjector</code> / <code>LazySyncBytecodeInjector</code></td><td>基于 ASM Tree API 的纯字节码注入器，向 <code>&lt;init&gt;</code> 与 <code>&lt;clinit&gt;</code> 末尾写入登记与绑定调用</td></tr></tbody></table>',26)])])}const h=o(r,[["render",n]]);export{g as __pageData,h as default};
